// Node "Kontext": collects the mail, the settings, the style guide and the document text, and writes the
// prompt for the AI (used only for PDFs and scans; e-invoices are read by Odoo).
const body = $('Rechnung eingegangen').first().json.body || {};
const settings = { ...($('Einstellungen').first().json.data || {}) };
const style = $('Stilregeln lesen').first().json.data || '';
const doc = $('Dokument erkennen').first().json;
const pdfText = String(doc.text || '').slice(0, 12000);
const id = String(body.message_id || 'web-' + Date.now()).replace(/[<>]/g, '');
const system = [
  'TASK: invoice_extract',
  'Du liest eine Eingangsrechnung (Text aus einem PDF) und gibst NUR ein JSON-Objekt zurück, ohne Text davor oder danach.',
  'Felder: supplier_name, supplier_vat (USt-IdNr. ohne Leerzeichen), supplier_iban (ohne Leerzeichen), invoice_number, invoice_date (YYYY-MM-DD),',
  'due_date (YYYY-MM-DD), po_ref (unsere Bestellnummer, z. B. "P00001", sonst null), currency, lines (Liste aus {code, description, quantity, unit_price, line_total}),',
  'net_total, vat_rate (z. B. 19), vat_amount, gross_total, note (Hinweise des Lieferanten, sonst null).',
  'Zahlen als Zahl mit Punkt (1234.5). Erfinde nichts: was nicht im Dokument steht, ist null.',
].join('\n');
const source = doc.source === 'ocr' ? 'per OCR aus einem Scan, kann Lesefehler enthalten' : 'aus dem PDF';
const user =
  `MESSAGE-ID: ${id}\nAbsender: ${body.from_name || ''} <${body.from_email || ''}>\nBetreff: ${body.subject || ''}\nDatei: ${body.filename || ''}\n\n` +
  `--- Text des Dokuments (${source}) ---\n${pdfText}`;
return [{ json: { id, mail: body, settings, style, doc, pdfChars: pdfText.length, extractPrompt: { system, user } } }];

// Node "E-Rechnung übernehmen": Odoo has already read the e-invoice (module account_edi_ubl_cii);
// its values are taken over unchanged. A supplier or bank account the importer created in the last
// 10 minutes counts as new (see "Limits" in the README for what that means).
const c = $('Kontext').first().json;
const result = n => $(n).first().json.result || [];
const bill = result('Beleg lesen')[0] || {};
const lines = result('Belegzeilen lesen').filter(l => !l.display_type || l.display_type === 'product');
const partner = result('Belegpartner lesen')[0] || null;
const bank = result('Bankkonto lesen')[0] || null;
const fresh = d => d && Date.now() - new Date(String(d).replace(' ', 'T') + 'Z').getTime() < 10 * 60 * 1000;
const vatPct = bill.amount_untaxed ? Math.round((bill.amount_tax / bill.amount_untaxed) * 1000) / 10 : null;
const inv = {
  supplier_name: partner ? partner.name : null,
  supplier_vat: partner && partner.vat ? partner.vat.replace(/\s/g, '').toUpperCase() : null,
  supplier_iban: bank ? bank.acc_number.replace(/\s/g, '').toUpperCase() : null,
  bank_new: !!(bank && fresh(bank.create_date)),
  partner_new: !!(partner && fresh(partner.create_date)),
  invoice_number: bill.ref || null,
  invoice_date: bill.invoice_date || null,
  due_date: bill.invoice_date_due || null,
  po_ref: bill.invoice_origin || null,
  currency: 'EUR',
  lines: lines.map(l => ({
    code: ((l.product_id && l.product_id[1]) || '').match(/\[(.*?)\]/)?.[1] || null,
    description: l.name, quantity: l.quantity, unit_price: l.price_unit, line_total: l.price_subtotal,
    move_line_id: l.id, linked_po_line: l.purchase_line_id ? l.purchase_line_id[0] : null,
  })),
  net_total: bill.amount_untaxed, vat_rate: vatPct, vat_amount: bill.amount_tax, gross_total: bill.amount_total, note: null,
};
const syntax = { zugferd: 'ZUGFeRD', cii: 'XRechnung CII' }[c.doc.syntax] || 'XRechnung UBL';
return [{ json: { ...c, inv, importedBillId: bill.id || null, readBy: `E-Rechnung (${syntax}), von Odoo selbst eingelesen, ohne KI` } }];

// One function builds the HTTP request for whichever AI the company chose in the settings.
// Keys come from the environment (.env.local) or, for "odoo", from the AI keys already stored in Odoo.
// Every provider gets the same prompts; only the request format differs (OpenAI, Anthropic or Azure).
const PROVIDERS = {
  mock:      { label: 'Testmodell (offline)', url: 'http://mock-llm:8099/v1', fmt: 'openai', local: true },
  ollama:    { label: 'Ollama (lokal)', url: 'http://host.docker.internal:11434/v1', fmt: 'openai', local: true, model: 'qwen2.5:7b' },
  lmstudio:  { label: 'LM Studio (lokal)', url: 'http://host.docker.internal:1234/v1', fmt: 'openai', local: true },
  openai:    { label: 'OpenAI', url: 'https://api.openai.com/v1', fmt: 'openai', env: 'OPENAI_API_KEY', model: 'gpt-4o-mini' },
  anthropic: { label: 'Anthropic Claude', url: 'https://api.anthropic.com/v1', fmt: 'anthropic', env: 'ANTHROPIC_API_KEY', model: 'claude-haiku-5-5' },
  gemini:    { label: 'Google Gemini', url: 'https://generativelanguage.googleapis.com/v1beta/openai', fmt: 'openai', env: 'GEMINI_API_KEY',
               model: 'gemini-2.5-flash' },
  mistral:   { label: 'Mistral', url: 'https://api.mistral.ai/v1', fmt: 'openai', env: 'MISTRAL_API_KEY', model: 'mistral-small-latest' },
  azure:     { label: 'Azure OpenAI', url: '', fmt: 'azure', env: 'AZURE_OPENAI_API_KEY' },
  custom:    { label: 'Eigener Endpunkt', url: '', fmt: 'openai', env: 'LLM_API_KEY' },
};

// "Wie in Odoo eingerichtet": find an AI key among the Odoo system parameters listed in the settings
function odooAiKey(s) {
  const rows = ($('KI aus Odoo lesen').first().json.result || []).filter(r => r.value);
  const prefer = s.odoo_ai_prefer || 'openai';
  const kind = r => (/openai/i.test(r.key) ? 'openai' : /google|gemini/i.test(r.key) ? 'gemini' : /anthropic|claude/i.test(r.key) ? 'anthropic' : null);
  const found = rows.map(r => ({ provider: kind(r), key: r.value, param: r.key })).filter(r => r.provider);
  return found.find(r => r.provider === prefer) || found[0] || null;
}

function llmRequest(s, system, user, temperature) {
  let p = s.llm_provider || 'mock', key = null, from = null;
  if (p === 'odoo') {
    const hit = odooAiKey(s);
    if (!hit)
      throw new Error(
        'In Odoo ist kein KI-Schlüssel hinterlegt (gesucht: ' + (s.odoo_ai_params || []).join(', ') + '). ' +
          'Bitte in den Einstellungen einen anderen KI-Anbieter wählen.',
      );
    p = hit.provider;
    key = hit.key;
    from = 'Odoo (' + hit.param + ')';
  }
  const P = PROVIDERS[p];
  if (!P) throw new Error('Unbekannter KI-Anbieter: ' + p);
  const base = String(s.llm_url || P.url).replace(/\/+$/, '');
  if (!base) throw new Error('Für ' + P.label + ' fehlt die Adresse (URL) in den Einstellungen.');
  key = key || (P.env ? $env[P.env] || $env.LLM_API_KEY : null) || null;
  if (P.env && !key) throw new Error('Für ' + P.label + ' fehlt der API-Schlüssel ' + P.env + ' in .env.local.');
  const model = (from ? s.odoo_ai_model || P.model : s.llm_model) || P.model || 'local-model';
  let url, body;
  const headers = { 'Content-Type': 'application/json' };
  if (P.fmt === 'anthropic') {
    url = base + '/messages';
    headers['x-api-key'] = key;
    headers['anthropic-version'] = '2023-06-01';
    body = { model, max_tokens: 1500, temperature, system, messages: [{ role: 'user', content: user }] };
  } else {
    url = P.fmt === 'azure'
      ? `${base}/openai/deployments/${encodeURIComponent(model)}/chat/completions?api-version=${s.azure_api_version || '2024-10-21'}`
      : base + '/chat/completions';
    if (key) {
      if (P.fmt === 'azure') headers['api-key'] = key;
      else headers['Authorization'] = 'Bearer ' + key;
    }
    body = { model, temperature, messages: [{ role: 'system', content: system }, { role: 'user', content: user }] };
  }
  return { url, headers, body, provider: p, label: P.label + (from ? ', Schlüssel aus ' + from : ''), model, local: !!P.local };
}

// Node "Lese-Anfrage": the HTTP request for the AI that reads a PDF or scan (llmRequest from shared/llm-request.js).
const c = $('Kontext').first().json;
return [{ json: { ...c, llm: llmRequest(c.settings, c.extractPrompt.system, c.extractPrompt.user, 0) } }];

// Reads the text out of an answer in OpenAI format (choices) or Anthropic format (content blocks).
const aiText = j => (j.choices?.[0]?.message?.content ?? (j.content || []).map(b => b.text || '').join('') ?? '');

// Node "KI-Antwort prüfen": turns the AI's answer into numbers. Nothing is decided here; the checks come next.
const c = $('Lese-Anfrage').first().json;
const raw = aiText($json) || '';
let inv = {};
try {
  inv = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1));
} catch (e) {
  inv = { parse_error: raw.slice(0, 200) };
}
const num = v => (v === null || v === undefined || v === '' ? null : Number(v));
inv.lines = (inv.lines || []).map(l => ({
  code: l.code || null, description: String(l.description || ''), quantity: num(l.quantity) || 0,
  unit_price: num(l.unit_price) || 0, line_total: num(l.line_total),
}));
for (const k of ['net_total', 'vat_rate', 'vat_amount', 'gross_total']) inv[k] = num(inv[k]);
inv.supplier_vat = inv.supplier_vat ? String(inv.supplier_vat).replace(/\s/g, '').toUpperCase() : null;
inv.supplier_iban = inv.supplier_iban ? String(inv.supplier_iban).replace(/\s/g, '').toUpperCase() : null;
const readBy = c.doc.source === 'ocr' ? 'Scan, per OCR gelesen, KI hat die Werte erkannt' : 'PDF-Text, KI hat die Werte erkannt';
return [{ json: { ...c, inv, readBy } }];

// Fixed invoice rules. None of them depends on the AI: they only do arithmetic on the values that were read.
// The builder puts this file in front of the "Prüfungen" and "Abgleich" Code nodes;
// test/rules.test.mjs tests the same functions.

// 2-decimal rounding and the 2-cent allowance used for every sum check
const r2 = v => Math.round(v * 100) / 100;
const near = (a, b) => a !== null && b !== null && Math.abs(a - b) <= 0.02;

// 1234.5 -> "1.234,50 €"; null -> "–"
const eu = v =>
  v === null || v === undefined
    ? '–'
    : Number(v).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ' €';

// German VAT ID (USt-IdNr.): check digit after ISO 7064 MOD 11,10. Other EU countries: format only.
function vatIdOk(v) {
  if (!/^DE\d{9}$/.test(v)) return /^[A-Z]{2}[0-9A-Z]{2,13}$/.test(v);
  let p = 10;
  for (const d of v.slice(2, 10)) {
    const s = (Number(d) + p) % 10 || 10;
    p = (2 * s) % 11;
  }
  const check = 11 - p === 10 ? 0 : 11 - p;
  return check === Number(v[10]);
}

// IBAN checksum (ISO 13616, mod 97 = 1). Expects the IBAN without spaces, upper case.
function ibanOk(iban) {
  const s = iban.slice(4) + iban.slice(0, 4);
  let r = 0;
  for (const ch of s) {
    const v = parseInt(ch, 36);
    r = Number(String(r) + String(v)) % 97;
  }
  return r === 1;
}

// Price on the invoice compared with the purchase order, in percent (+7.2 = 7.2 % more expensive)
const priceDiffPct = (price, orderPrice) => (orderPrice ? ((price - orderPrice) / orderPrice) * 100 : 0);
const priceOutsideTolerance = (price, orderPrice, tolPct) => Math.abs(priceDiffPct(price, orderPrice)) > tolPct;

// More billed than delivered and not yet billed? (1e-9 absorbs floating point noise)
const qtyOverOpen = (qty, open) => qty > open + 1e-9;

// Node "Prüfungen": the fixed checks on the invoice itself (sums, VAT, VAT ID, IBAN, records the importer just created).
// Uses r2, near, eu, vatIdOk and ibanOk from rules/invoice-rules.js.
const c = $json, inv = c.inv;
const checks = [];
const warn = text => checks.push({ level: 'warn', text });
const block = (text, extra) => checks.push({ level: 'block', text, ...extra });

if (inv.parse_error) block('Rechnung konnte nicht gelesen werden.');

// each line: quantity × price = line total
inv.lines.forEach((l, i) => {
  const calc = r2(l.quantity * l.unit_price);
  if (l.line_total !== null && !near(calc, l.line_total))
    warn(`Position ${i + 1}: Menge × Preis ergibt ${eu(calc)}, nicht ${eu(l.line_total)}.`);
});

// lines add up to the net total, VAT is right, net + VAT = gross
const sumLines = r2(inv.lines.reduce((s, l) => s + l.quantity * l.unit_price, 0));
if (inv.net_total !== null && !near(sumLines, inv.net_total))
  warn(`Summe der Positionen ${eu(sumLines)} weicht vom Nettobetrag ${eu(inv.net_total)} ab.`);
if (inv.net_total !== null && inv.vat_rate !== null && inv.vat_amount !== null) {
  const vat = r2((inv.net_total * inv.vat_rate) / 100);
  if (!near(vat, inv.vat_amount))
    warn(`Umsatzsteuer: ${inv.vat_rate} % von ${eu(inv.net_total)} sind ${eu(vat)}, auf der Rechnung ${eu(inv.vat_amount)}.`);
}
if (inv.net_total !== null && inv.vat_amount !== null && inv.gross_total !== null) {
  const gross = r2(inv.net_total + inv.vat_amount);
  if (!near(gross, inv.gross_total))
    warn(`Rechenfehler: Netto ${eu(inv.net_total)} + USt ${eu(inv.vat_amount)} = ${eu(gross)}, auf der Rechnung steht ${eu(inv.gross_total)}.`);
}

// VAT ID and IBAN check digits
if (!inv.supplier_vat) warn('Keine USt-IdNr. auf der Rechnung (Pflichtangabe nach § 14 UStG, oder Steuernummer).');
else if (!vatIdOk(inv.supplier_vat)) warn(`USt-IdNr. ${inv.supplier_vat} hat keine gültige Prüfziffer.`);
if (inv.supplier_iban && !ibanOk(inv.supplier_iban)) block(`IBAN ${inv.supplier_iban} ist ungültig (Prüfsumme).`);

// e-invoices: a supplier or bank account that Odoo's importer had to create is not a known one
if (inv.partner_new)
  block(`Lieferant "${inv.supplier_name}" wurde gerade erst beim Einlesen neu angelegt, ist also kein bekannter Lieferant.`);
if (inv.bank_new)
  block(
    `Bankverbindung ${inv.supplier_iban} wurde beim Einlesen neu angelegt und war vorher nicht in Odoo. ` +
      'Nicht per E-Mail klären, beim Lieferanten unter der bekannten Telefonnummer nachfragen.',
    { fraud: true },
  );

return [{ json: { ...c, inv, checks } }];

// Fixed invoice rules. None of them depends on the AI: they only do arithmetic on the values that were read.
// The builder puts this file in front of the "Prüfungen" and "Abgleich" Code nodes;
// test/rules.test.mjs tests the same functions.

// 2-decimal rounding and the 2-cent allowance used for every sum check
const r2 = v => Math.round(v * 100) / 100;
const near = (a, b) => a !== null && b !== null && Math.abs(a - b) <= 0.02;

// 1234.5 -> "1.234,50 €"; null -> "–"
const eu = v =>
  v === null || v === undefined
    ? '–'
    : Number(v).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ' €';

// German VAT ID (USt-IdNr.): check digit after ISO 7064 MOD 11,10. Other EU countries: format only.
function vatIdOk(v) {
  if (!/^DE\d{9}$/.test(v)) return /^[A-Z]{2}[0-9A-Z]{2,13}$/.test(v);
  let p = 10;
  for (const d of v.slice(2, 10)) {
    const s = (Number(d) + p) % 10 || 10;
    p = (2 * s) % 11;
  }
  const check = 11 - p === 10 ? 0 : 11 - p;
  return check === Number(v[10]);
}

// IBAN checksum (ISO 13616, mod 97 = 1). Expects the IBAN without spaces, upper case.
function ibanOk(iban) {
  const s = iban.slice(4) + iban.slice(0, 4);
  let r = 0;
  for (const ch of s) {
    const v = parseInt(ch, 36);
    r = Number(String(r) + String(v)) % 97;
  }
  return r === 1;
}

// Price on the invoice compared with the purchase order, in percent (+7.2 = 7.2 % more expensive)
const priceDiffPct = (price, orderPrice) => (orderPrice ? ((price - orderPrice) / orderPrice) * 100 : 0);
const priceOutsideTolerance = (price, orderPrice, tolPct) => Math.abs(priceDiffPct(price, orderPrice)) > tolPct;

// More billed than delivered and not yet billed? (1e-9 absorbs floating point noise)
const qtyOverOpen = (qty, open) => qty > open + 1e-9;

// Node "Abgleich": compares the invoice with Odoo (supplier, bank account, duplicates, purchase order, goods receipt)
// and prepares the draft vendor bill. Uses eu, priceDiffPct, priceOutsideTolerance and qtyOverOpen from rules/invoice-rules.js.
const c = $('Prüfungen').first().json;
const s = c.settings, inv = c.inv, checks = [...c.checks];
const result = n => $(n).first().json.result || [];
const supplier = result('Lieferant suchen')[0] || null;
const banks = supplier ? result('Bankkonten lesen') : [];
const pos = supplier ? result('Bestellungen suchen') : [];
const poLines = supplier ? result('Bestellpositionen lesen') : [];
const dupes = supplier ? result('Dubletten prüfen') : [];
const tol = Number(s.inv_price_tolerance_pct ?? 2);
const warn = text => checks.push({ level: 'warn', text });
const block = (text, extra) => checks.push({ level: 'block', text, ...extra });
const clean = x => String(x || '').replace(/\s/g, '').toUpperCase();

// supplier, duplicate, bank account, VAT ID
if (!supplier) block(`Lieferant "${inv.supplier_name}" (${inv.supplier_vat || 'ohne USt-IdNr.'}) ist nicht in Odoo angelegt.`);
if (dupes.length) {
  const state = d => ({ draft: 'Entwurf', posted: 'gebucht' })[d.state] || d.state;
  const found = dupes.map(d => (d.name && d.name !== '/' ? d.name + ', ' : '') + state(d)).join('; ');
  block(`Rechnung ${inv.invoice_number} ist schon erfasst (${found}).`);
}
if (supplier && inv.supplier_iban && banks.length && !banks.some(b => clean(b.acc_number) === inv.supplier_iban))
  block(
    `Bankverbindung weicht ab: Rechnung ${inv.supplier_iban}, in Odoo ${banks.map(b => clean(b.acc_number)).join(', ')}. ` +
      'Nicht per E-Mail klären, beim Lieferanten unter der bekannten Telefonnummer nachfragen.',
    { fraud: true },
  );
if (supplier && supplier.vat && inv.supplier_vat && clean(supplier.vat) !== inv.supplier_vat)
  warn(`USt-IdNr. auf der Rechnung (${inv.supplier_vat}) passt nicht zu Odoo (${supplier.vat}).`);

// pick the purchase order: the one named on the invoice, or the only open one whose lines fit
const byPo = {};
for (const l of poLines) (byPo[l.order_id[0]] = byPo[l.order_id[0]] || []).push(l);
const code = l => (l.name.match(/\[(.*?)\]/) || [])[1] || '';
const fits = (pl, il) =>
  (il.code && code(pl).toUpperCase() === String(il.code).toUpperCase()) ||
  (il.description && pl.name.toLowerCase().includes(il.description.toLowerCase().slice(0, 18)));
let po = null, poNote = null;
if (inv.po_ref) {
  po = pos.find(p => p.name === inv.po_ref || p.partner_ref === inv.po_ref || p.origin === inv.po_ref) || null;
  if (!po && supplier) warn(`Bestellung ${inv.po_ref} gibt es bei diesem Lieferanten in Odoo nicht.`);
} else if (supplier) {
  const open = pos.filter(p =>
    inv.lines.every(il => (byPo[p.id] || []).some(pl => fits(pl, il) && pl.qty_received - pl.qty_invoiced >= il.quantity)),
  );
  if (open.length === 1) {
    po = open[0];
    poNote = `Keine Bestellnummer auf der Rechnung; zugeordnet über Lieferant und Artikel: ${po.name}.`;
  } else
    warn(open.length ? `Keine Bestellnummer; ${open.length} offene Bestellungen passen, bitte zuordnen.` : 'Keine Bestellnummer und keine passende offene Bestellung.');
}

// 3-way match per line: ordered, received, already invoiced, this invoice
const rows = inv.lines.map((il, i) => {
  const pl = po ? (byPo[po.id] || []).find(l => fits(l, il)) : null;
  // a bill Odoo imported may already be linked to this order line; don't count it against itself
  const self = pl && inv.lines[i] && inv.lines[i].linked_po_line === pl.id ? il.quantity : 0;
  const row = {
    pos: i + 1, text: il.description, code: il.code, qty: il.quantity, price: il.unit_price,
    ordered: pl ? pl.product_qty : null, received: pl ? pl.qty_received : null,
    invoiced: pl ? pl.qty_invoiced - self : null, po_price: pl ? pl.price_unit : null, issues: [],
  };
  if (po && !pl) row.issues.push('nicht bestellt');
  if (pl) {
    const open = pl.qty_received - (pl.qty_invoiced - self);
    if (qtyOverOpen(il.quantity, open)) row.issues.push(`Menge ${il.quantity} > geliefert und noch nicht berechnet ${open}`);
    if (priceOutsideTolerance(il.unit_price, pl.price_unit, tol)) {
      const diff = priceDiffPct(il.unit_price, pl.price_unit);
      row.issues.push(`Preis ${eu(il.unit_price)} statt ${eu(pl.price_unit)} (${diff > 0 ? '+' : ''}${diff.toFixed(1).replace('.', ',')} %)`);
    }
    row.line = pl;
  }
  if (dupes.length) row.issues = [];
  row.issues.forEach(t => warn(`Position ${i + 1} (${il.code || il.description}): ${t}.`));
  return row;
});

const blocked = checks.some(x => x.level === 'block');
const decision = blocked ? 'blockiert' : checks.length ? 'abweichung' : 'ok';

// the draft vendor bill: an e-invoice is already a draft in Odoo (only the order lines are linked); otherwise create one
let draft = null;
if (c.importedBillId && !blocked)
  draft = { model: 'account.move', method: 'write', args: [[c.importedBillId], {
    invoice_origin: po ? po.name : false,
    narration: `Automatisch erfasst aus ${c.mail.filename || 'E-Rechnung'} (${c.id}); E-Rechnung von Odoo eingelesen.`,
    invoice_line_ids: rows
      .filter(r => r.line && !inv.lines[r.pos - 1].linked_po_line)
      .map(r => [1, inv.lines[r.pos - 1].move_line_id, { purchase_line_id: r.line.id }]),
  }] };
else if (!blocked && supplier)
  draft = { model: 'account.move', method: 'create', values: {
    move_type: 'in_invoice', partner_id: supplier.id, ref: inv.invoice_number,
    invoice_date: inv.invoice_date, invoice_date_due: inv.due_date || false, invoice_origin: po ? po.name : false,
    partner_bank_id: (banks.find(b => clean(b.acc_number) === inv.supplier_iban) || {}).id || false,
    narration: `Automatisch erfasst aus ${c.mail.filename || 'PDF'} (${c.id}).`,
    invoice_line_ids: rows.map(r => [0, 0, r.line
      ? { product_id: r.line.product_id[0], name: r.line.name, quantity: r.qty, price_unit: r.price, purchase_line_id: r.line.id, tax_ids: [[6, 0, r.line.taxes_id]] }
      : { name: r.text, quantity: r.qty, price_unit: r.price }]),
